//! Parity of `hece_core::textnorm` with the fixture generated by the reference implementation.
#![allow(clippy::unwrap_used, reason = "tests may unwrap")]

use hece_core::textnorm::{expand_numbers, normalize_words, spell_acronyms, turkish_lower};
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    input: String,
    expand_numbers: String,
    spell_acronyms: String,
    normalize_words: Vec<String>,
}

fn cases() -> Vec<Case> {
    serde_json::from_str(include_str!("fixtures/textnorm_expected.json")).unwrap()
}

#[test]
fn fixture_has_enough_cases() {
    assert!(cases().len() >= 40);
}

#[test]
fn expand_numbers_matches_reference() {
    for case in cases() {
        assert_eq!(
            expand_numbers(&case.input),
            case.expand_numbers,
            "input: {:?}",
            case.input
        );
    }
}

#[test]
fn spell_acronyms_matches_reference() {
    for case in cases() {
        assert_eq!(
            spell_acronyms(&case.input),
            case.spell_acronyms,
            "input: {:?}",
            case.input
        );
    }
}

#[test]
fn normalize_words_matches_reference() {
    for case in cases() {
        assert_eq!(
            normalize_words(&case.input),
            case.normalize_words,
            "input: {:?}",
            case.input
        );
    }
}

#[test]
fn turkish_casing_is_identical() {
    assert_eq!(
        normalize_words("İSTANBUL'DA"),
        normalize_words("istanbulda")
    );
    assert_eq!(normalize_words("IŞIK"), normalize_words("ışık"));
    assert_eq!(turkish_lower("IİıiŞ"), "ıiıiş");
}

#[test]
fn nfc_decomposed_input_matches_composed() {
    assert_eq!(normalize_words("Su\u{308}t"), normalize_words("Süt"));
}
